<?php
namespace App\Controllers;

use App\Core\Database;
use App\Helpers\AuthHelper;
use App\Helpers\NotificationHelper;
use App\Services\StockService;
use PDO;

class ReturnWorkflowController extends ReturnController
{
    private function go(string $p): void { header('Location: '.url($p)); exit; }
    private function audit(PDO $pdo,int $uid,string $action,int $id,string $note,?array $old=null,?array $new=null):void {
        $q=$pdo->prepare("INSERT INTO audit_logs (user_id,action,entity,entity_id,old_data,new_data,ip_address,user_agent) VALUES (?,?,'returns',?,?,?,?,?)");
        $q->execute([$uid,$action,$id,$old?json_encode($old,JSON_UNESCAPED_UNICODE):null,json_encode(array_merge($new??[],['notes'=>$note]),JSON_UNESCAPED_UNICODE),$_SERVER['REMOTE_ADDR']??null,$_SERVER['HTTP_USER_AGENT']??null]);
    }
    public function index(){
        $pdo=Database::getInstance()->getConnection();$u=AuthHelper::user();$search=trim($_GET['search']??'');$status=trim($_GET['status']??'');$page=max(1,(int)($_GET['page']??1));$limit=15;$offset=($page-1)*$limit;$where=['1=1'];$p=[];
        if(!AuthHelper::hasRole(['SUPERADMIN','ADMIN'])){$where[]='r.technician_id=?';$p[]=(int)$u['id'];}
        if($search!==''){$where[]='(t.name LIKE ? OR w.name LIKE ?)';$p[]="%$search%";$p[]="%$search%";}
        if($status!==''){$where[]='r.status=?';$p[]=$status;}$ws='WHERE '.implode(' AND ',$where);
        $c=$pdo->prepare("SELECT COUNT(*) FROM returns r JOIN users t ON t.id=r.technician_id JOIN warehouses w ON w.id=r.warehouse_id $ws");$c->execute($p);$totalItems=(int)$c->fetchColumn();$totalPages=max(1,(int)ceil($totalItems/$limit));
        $s=$pdo->prepare("SELECT r.*,t.name technician_name,w.name warehouse_name FROM returns r JOIN users t ON t.id=r.technician_id JOIN warehouses w ON w.id=r.warehouse_id $ws ORDER BY r.id DESC LIMIT $limit OFFSET $offset");$s->execute($p);$returns=$s->fetchAll(PDO::FETCH_ASSOC);
        require __DIR__.'/../../resources/views/workflow/returns/index.php';
    }
    public function create(){
        AuthHelper::requireRole(['TEKNISI_NOC']);$pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];$q=$pdo->prepare("SELECT l.id,w.name warehouse_name FROM loans l JOIN warehouses w ON w.id=l.warehouse_id WHERE l.borrower_id=? AND l.status IN ('BORROWED','PARTIAL_RETURNED') ORDER BY l.id DESC");$q->execute([$uid]);$loans=$q->fetchAll(PDO::FETCH_ASSOC);$warehouses=$pdo->query("SELECT id,name FROM warehouses WHERE is_active=1 ORDER BY name")->fetchAll(PDO::FETCH_ASSOC);require __DIR__.'/../../resources/views/workflow/returns/create.php';
    }
    public function apiLoanItems(){
        header('Content-Type: application/json');$loanId=(int)($_GET['loan_id']??0);$pdo=Database::getInstance()->getConnection();$u=AuthHelper::user();$q=$pdo->prepare("SELECT id,borrower_id,status FROM loans WHERE id=?");$q->execute([$loanId]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan||($u['role']==='TEKNISI_NOC'&&(int)$loan['borrower_id']!==(int)$u['id'])||!in_array($loan['status'],['BORROWED','PARTIAL_RETURNED'],true)){echo json_encode([]);return;}
        $items=[];$q=$pdo->prepare("SELECT li.id loan_item_id,li.master_item_id,m.nama,m.is_serialized,li.quantity,li.returned_quantity FROM loan_items li JOIN master_items m ON m.id=li.master_item_id WHERE li.loan_id=? AND li.quantity>li.returned_quantity");$q->execute([$loanId]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r){$r['source_type']='STOCK';$r['remaining_quantity']=(int)$r['quantity']-(int)$r['returned_quantity'];$r['serials']=[];if((int)$r['is_serialized']===1){$sn=$pdo->prepare("SELECT sn.id,sn.serial_number FROM loan_item_serials lis JOIN serial_numbers sn ON sn.id=lis.serial_number_id WHERE lis.loan_item_id=? AND lis.status='BORROWED' ORDER BY sn.serial_number");$sn->execute([(int)$r['loan_item_id']]);$r['serials']=$sn->fetchAll(PDO::FETCH_ASSOC);} $items[]=$r;}
        $q=$pdo->prepare("SELECT id manual_item_id,name nama,quantity,returned_quantity,unit FROM loan_manual_items WHERE loan_id=? AND quantity>returned_quantity ORDER BY id");$q->execute([$loanId]);foreach($q->fetchAll(PDO::FETCH_ASSOC) as $r){$r['source_type']='MANUAL';$r['is_serialized']=0;$r['remaining_quantity']=(int)$r['quantity']-(int)$r['returned_quantity'];$r['serials']=[];$items[]=$r;}echo json_encode($items);
    }
    public function store(){
        AuthHelper::requireRole(['TEKNISI_NOC']);if(!hash_equals($_SESSION['csrf_token']??'',$_POST['csrf_token']??'')){$_SESSION['error']='CSRF validation gagal.';$this->go('/returns/create');}
        $pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];$loanId=(int)($_POST['loan_id']??0);$warehouseId=(int)($_POST['warehouse_id']??0);$notes=trim($_POST['notes']??'');$sources=$_POST['source_types']??[];$loanItemIds=$_POST['loan_item_ids']??[];$manualIds=$_POST['manual_item_ids']??[];$qtys=$_POST['quantities']??[];$serialIds=$_POST['serial_ids']??[];
        if($loanId<=0||$warehouseId<=0||!$sources){$_SESSION['error']='Peminjaman, gudang tujuan, dan barang wajib dipilih.';$this->go('/returns/create');}
        try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM loans WHERE id=? AND borrower_id=? AND status IN ('BORROWED','PARTIAL_RETURNED') FOR UPDATE");$q->execute([$loanId,$uid]);$loan=$q->fetch(PDO::FETCH_ASSOC);if(!$loan)throw new \Exception('Peminjaman tidak valid atau sudah selesai.');$code=\App\Helpers\TransactionHelper::generateCode('RET','returns');$q=$pdo->prepare("INSERT INTO returns(transaction_code,reference_type,reference_id,technician_id,warehouse_id,notes,status) VALUES(?,'LOAN',?,?,?,?, 'PENDING')");$q->execute([$code,$loanId,$uid,$warehouseId,$notes]);$returnId=(int)$pdo->lastInsertId();$ins=$pdo->prepare("INSERT INTO return_items(return_id,master_item_id,serial_number_id,quantity,condition_status,loan_item_id,loan_manual_item_id) VALUES(?,?,?,?, 'PENDING',?,?)");$lines=0;
            foreach($sources as $i=>$source){$qty=max(0,(int)($qtys[$i]??0));if($qty<1)continue;if($source==='MANUAL'){$mid=(int)($manualIds[$i]??0);$x=$pdo->prepare("SELECT id,quantity,returned_quantity FROM loan_manual_items WHERE id=? AND loan_id=? FOR UPDATE");$x->execute([$mid,$loanId]);$m=$x->fetch(PDO::FETCH_ASSOC);if(!$m||$qty>((int)$m['quantity']-(int)$m['returned_quantity']))throw new \Exception('Jumlah barang manual melebihi sisa pinjaman.');$ins->execute([$returnId,null,null,$qty,$mid]);$lines++;continue;}
                $lid=(int)($loanItemIds[$i]??0);$x=$pdo->prepare("SELECT li.*,m.nama,m.is_serialized FROM loan_items li JOIN master_items m ON m.id=li.master_item_id WHERE li.id=? AND li.loan_id=? FOR UPDATE");$x->execute([$lid,$loanId]);$item=$x->fetch(PDO::FETCH_ASSOC);if(!$item||$qty>((int)$item['quantity']-(int)$item['returned_quantity']))throw new \Exception('Jumlah pengembalian melebihi sisa barang.');
                if((int)$item['is_serialized']===1){$sel=array_values(array_filter(array_map('intval',(array)($serialIds[$i]??[]))));if(count($sel)!==$qty)throw new \Exception("Pilih $qty serial number untuk {$item['nama']}.");foreach($sel as $snId){$v=$pdo->prepare("SELECT id FROM loan_item_serials WHERE loan_item_id=? AND serial_number_id=? AND status='BORROWED'");$v->execute([$lid,$snId]);if(!$v->fetch())throw new \Exception('Serial yang dipilih tidak termasuk dalam peminjaman.');$ins->execute([$returnId,$item['master_item_id'],$snId,1,$lid,null]);$lines++;}}
                else{$ins->execute([$returnId,$item['master_item_id'],null,$qty,$lid,null]);$lines++;}
            }
            if($lines===0)throw new \Exception('Tidak ada barang valid untuk dikembalikan.');$this->audit($pdo,$uid,'RETURN_REQUEST',$returnId,'Teknisi mengajukan pengembalian barang.',null,['status'=>'PENDING']);$pdo->commit();NotificationHelper::createForRoleOnce('ADMIN','Pengembalian Menunggu Proses',AuthHelper::user()['name'].' mengajukan pengembalian barang.','info','/returns/show?id='.$returnId);$_SESSION['success']='Pengembalian berhasil diajukan dan menunggu proses Admin.';
        }catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal mengajukan pengembalian: '.$e->getMessage();}$this->go('/returns');
    }
    public function show(){
        $id=(int)($_GET['id']??0);$pdo=Database::getInstance()->getConnection();$u=AuthHelper::user();$q=$pdo->prepare("SELECT r.*,t.name technician_name,w.name warehouse_name FROM returns r JOIN users t ON t.id=r.technician_id JOIN warehouses w ON w.id=r.warehouse_id WHERE r.id=?");$q->execute([$id]);$return=$q->fetch(PDO::FETCH_ASSOC);if(!$return){$_SESSION['error']='Pengembalian tidak ditemukan.';$this->go('/returns');}if($u['role']==='TEKNISI_NOC'&&(int)$return['technician_id']!==(int)$u['id']){$_SESSION['error']='Anda tidak memiliki akses.';$this->go('/returns');}$q=$pdo->prepare("SELECT ri.*,m.nama,m.is_serialized,sn.serial_number,mi.name manual_name,mi.unit manual_unit FROM return_items ri LEFT JOIN master_items m ON m.id=ri.master_item_id LEFT JOIN serial_numbers sn ON sn.id=ri.serial_number_id LEFT JOIN loan_manual_items mi ON mi.id=ri.loan_manual_item_id WHERE ri.return_id=? ORDER BY ri.id");$q->execute([$id]);$items=$q->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare("SELECT a.*,u.name user_name FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id WHERE a.entity='returns' AND a.entity_id=? ORDER BY a.created_at DESC,a.id DESC");$q->execute([$id]);$timeline=$q->fetchAll(PDO::FETCH_ASSOC);require __DIR__.'/../../resources/views/workflow/returns/show.php';
    }
    public function process(){
        AuthHelper::requireRole(['ADMIN']);AuthHelper::denySuperadminWrite();if(!hash_equals($_SESSION['csrf_token']??'',$_POST['csrf_token']??'')){$_SESSION['error']='CSRF validation gagal.';$this->go('/returns');}$id=(int)($_POST['id']??0);$pdo=Database::getInstance()->getConnection();$uid=(int)AuthHelper::user()['id'];$conditions=$_POST['conditions']??[];$svc=new StockService();
        try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT * FROM returns WHERE id=? FOR UPDATE");$q->execute([$id]);$ret=$q->fetch(PDO::FETCH_ASSOC);if(!$ret||$ret['status']!=='PENDING')throw new \Exception('Pengembalian sudah diproses atau tidak valid.');$q=$pdo->prepare("SELECT ri.*,m.is_serialized FROM return_items ri LEFT JOIN master_items m ON m.id=ri.master_item_id WHERE ri.return_id=? FOR UPDATE");$q->execute([$id]);$items=$q->fetchAll(PDO::FETCH_ASSOC);
            foreach($items as $item){$cond=$conditions[$item['id']]??'GOOD';$good=in_array($cond,['GOOD','BAIK','AVAILABLE'],true);$pdo->prepare("UPDATE return_items SET condition_status=? WHERE id=?")->execute([$cond,$item['id']]);
                if($item['loan_manual_item_id']){$pdo->prepare("UPDATE loan_manual_items SET returned_quantity=returned_quantity+? WHERE id=?")->execute([(int)$item['quantity'],(int)$item['loan_manual_item_id']]);continue;}
                if($item['loan_item_id'])$pdo->prepare("UPDATE loan_items SET returned_quantity=returned_quantity+? WHERE id=?")->execute([(int)$item['quantity'],(int)$item['loan_item_id']]);
                if($item['serial_number_id']){$sn=(int)$item['serial_number_id'];$new=$good?'AVAILABLE':'BROKEN';$svc->moveSerial($sn,$new,(int)$ret['warehouse_id'],null,null,'return',$id,'Pengembalian barang.', $cond);$pdo->prepare("UPDATE loan_item_serials SET status='RETURNED' WHERE loan_item_id=? AND serial_number_id=?")->execute([(int)$item['loan_item_id'],$sn]);if($good)$svc->mutateStock((int)$item['master_item_id'],(int)$ret['warehouse_id'],1,'RETURN','returns',$id,'Barang serial kembali.');}
                elseif($good&&$item['master_item_id'])$svc->mutateStock((int)$item['master_item_id'],(int)$ret['warehouse_id'],(int)$item['quantity'],'RETURN','returns',$id,'Barang bulk kembali.');
            }
            $loanId=(int)$ret['reference_id'];if($loanId){$s=$pdo->prepare("SELECT (SELECT COALESCE(SUM(quantity),0) FROM loan_items WHERE loan_id=?)+(SELECT COALESCE(SUM(quantity),0) FROM loan_manual_items WHERE loan_id=?) total_qty,(SELECT COALESCE(SUM(returned_quantity),0) FROM loan_items WHERE loan_id=?)+(SELECT COALESCE(SUM(returned_quantity),0) FROM loan_manual_items WHERE loan_id=?) total_returned");$s->execute([$loanId,$loanId,$loanId,$loanId]);$st=$s->fetch(PDO::FETCH_ASSOC);$loanStatus=(int)$st['total_returned']>=(int)$st['total_qty']?'RETURNED':'PARTIAL_RETURNED';$pdo->prepare("UPDATE loans SET status=? WHERE id=?")->execute([$loanStatus,$loanId]);}
            $pdo->prepare("UPDATE returns SET status='COMPLETED',processed_by=? WHERE id=?")->execute([$uid,$id]);$this->audit($pdo,$uid,'RETURN_PROCESSED',$id,'Pengembalian diperiksa dan diproses Admin.',['status'=>'PENDING'],['status'=>'COMPLETED']);$pdo->commit();NotificationHelper::createForUsers([(int)$ret['technician_id']],'Pengembalian Diproses','Pengembalian barang Anda sudah diproses Admin.','success','/returns/show?id='.$id);$_SESSION['success']='Pengembalian berhasil diproses.';
        }catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$_SESSION['error']='Gagal memproses pengembalian: '.$e->getMessage();}$this->go('/returns/show?id='.$id);
    }
}
